CREATE DEFINER=`yazmin.esquivel`@`%` FUNCTION `fn_estado_prueba`(
    p_posicion INT,
    p_total INT,
    p_porcentaje_activos DECIMAL(5,2)
) RETURNS tinyint
    NO SQL
    DETERMINISTIC
BEGIN
    IF p_posicion <= ROUND(
        p_total * p_porcentaje_activos / 100, 0
    ) THEN
        RETURN 1;
    END IF;

    RETURN 0;
END ;;
DELIMITER ;
